Lemma put_R_acc : forall m ff (c0 c1 c2 c3 c10 c11 c12 c13 c14 c15 : byte),
  0 <= ff -> ff mod 8 = 0 -> ff + 128 <= AAPP_HI ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880)
    [C1 c0; C1 c1; C1 c2; C1 c3; C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 c10; C1 c11; C1 c12; C1 c13; C1 c14; C1 c15] ->
  accessible m (ff + 32) 48.
Proof.
  intros m ff c0 c1 c2 c3 c10 c11 c12 c13 c14 c15 F0 F8 FH C.
  pose proof (proj1 (rw_cells_app bsegs m _ [C1 c0; C1 c1; C1 c2; C1 c3]
                                 [C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 c10; C1 c11; C1 c12; C1 c13; C1 c14; C1 c15]) C) as [_ C4_].
  pose proof (proj1 (rw_cells_app bsegs m _ [C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0)] [C1 c10; C1 c11; C1 c12; C1 c13; C1 c14; C1 c15]) C4_) as [C46 _].
  cbn [cells_size csize Nat.add] in C46.
  rewrite <- (app_nil_r [C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0)]) in C46. apply (rw_cells_merge bsegs _ _ [] _ []) in C46.
  cbn [cells_size csize cells_bytes cbytes app Nat.add] in C46.
  replace 48 with (8 * 6) by lia.
  eapply (prep_frame_acc m ff 32 6); [exact F0| exact F8| lia| reflexivity| lia| lia| | reflexivity].
  replace (Z.shiftr ff 3 + 2147450880 + 32 / 8) with (Z.shiftr ff 3 + 2147450880 + Z.of_nat 4) by (clear; lia). exact C46.
Qed.
